// --- Issue #1: brick bounce -------------------------------------------------
//
// The ball must bounce off bricks like a real arcade game: per-face flips,
// corner double flips, push-out (no sticky re-flip), exactly one bounce across
// a seam, and a sweep so a fast ball cannot tunnel through a brick.

// Bottom row / top-left corner of the grid: clean approach lanes with no
// brick below (bottom row) or above (top row), so a single brick is hit.
function bottomRowBricks(state, colIndex) {
  return state.bricks.filter((b) => b.row === 4).sort((a, b) => a.x - b.x)[colIndex];
}

function topLeftBrick(state) {
  return state.bricks.filter((b) => b.row === 0).sort((a, b) => a.x - b.x)[0];
}

test('#1 bottom face: a rising ball bounces down and is pushed below the brick', () => {
  const state = createState(1);
  const brick = bottomRowBricks(state, 0);
  const cx = brick.x + brick.w / 2;
  state.ball = { x: cx, y: brick.y + brick.h - 5, r: BALL_R, vx: 0, vy: -300, px: cx, py: brick.y + brick.h + 40 };

  const destroyed = resolveBrickHit(state);

  assert.equal(destroyed, 1);
  assert.equal(brick.alive, false, 'the brick is destroyed');
  assert.ok(state.ball.vy > 0, 'vy flips toward DOWN on a bottom-face hit');
  assert.equal(state.ball.vx, 0, 'vx is left untouched');
  assert.ok(state.ball.y >= brick.y + brick.h + BALL_R - 1e-9, 'the ball is pushed back below the brick');
  assert.equal(collides(state.ball, brick), false, 'no overlap left for the next frame');
});

test('#1 top face: a falling ball bounces up and is pushed above the brick', () => {
  const state = createState(1);
  const brick = topLeftBrick(state);
  const cx = brick.x + brick.w / 2;
  state.ball = { x: cx, y: brick.y + 5, r: BALL_R, vx: 0, vy: 300, px: cx, py: brick.y - 40 };

  const destroyed = resolveBrickHit(state);

  assert.equal(destroyed, 1);
  assert.ok(state.ball.vy < 0, 'vy flips toward UP on a top-face hit');
  assert.equal(state.ball.vx, 0, 'vx is left untouched');
  assert.ok(state.ball.y <= brick.y - BALL_R + 1e-9, 'the ball is pushed back above the brick');
  assert.equal(collides(state.ball, brick), false);
});

test('#1 side face: a ball moving right bounces left and is pushed out sideways', () => {
  const state = createState(1);
  const brick = bottomRowBricks(state, 0);
  const cy = brick.y + brick.h / 2;
  state.ball = { x: brick.x - 15, y: cy, r: BALL_R, vx: 300, vy: 0, px: brick.x - 40, py: cy };

  const destroyed = resolveBrickHit(state);

  assert.equal(destroyed, 1);
  assert.ok(state.ball.vx < 0, 'vx flips toward LEFT on a left-face hit');
  assert.equal(state.ball.vy, 0, 'vy is left untouched');
  assert.ok(state.ball.x <= brick.x - BALL_R + 1e-9, 'the ball is pushed out to the left');
  assert.equal(collides(state.ball, brick), false);
});

test('#1 corner: a diagonal hit on a corner flips both components', () => {
  const state = createState(1);
  const brick = bottomRowBricks(state, 0);
  // 45° path entering the inflated rectangle exactly at its bottom-left corner
  state.ball = {
    x: brick.x + 20, y: brick.y, r: BALL_R, vx: 300, vy: -300,
    px: brick.x - 40, py: brick.y + brick.h + 40,
  };

  const destroyed = resolveBrickHit(state);

  assert.equal(destroyed, 1);
  assert.ok(state.ball.vx < 0 && state.ball.vy > 0, 'a corner hit flips vx AND vy');
  assert.ok(Math.abs(state.ball.x - (brick.x - BALL_R)) < 1e-6, 'pushed out at the left corner');
  assert.ok(Math.abs(state.ball.y - (brick.y + brick.h + BALL_R)) < 1e-6, 'pushed out at the bottom corner');
  assert.equal(collides(state.ball, brick), false);
});

test('#1 neighbours: a seam hit destroys both bricks and bounces exactly once', () => {
  const state = createState(1);
  const row2 = state.bricks.filter((b) => b.row === 2).sort((a, b) => a.x - b.x);
  const a = row2[3];
  const b = row2[4];
  // Clear the two columns below the seam so the ball only meets a and b.
  state.bricks.filter((br) => br.row >= 3 && (br.x === a.x || br.x === b.x)).forEach((br) => { br.alive = false; });
  const seamX = a.x + a.w + BRICK_GAP / 2;
  state.ball = { x: seamX, y: a.y + a.h - 5, r: BALL_R, vx: 0, vy: -300, px: seamX, py: a.y + a.h + 40 };

  const destroyed = resolveBrickHit(state);

  assert.equal(destroyed, 2, 'both bricks of the seam are destroyed');
  assert.equal(a.alive, false);
  assert.equal(b.alive, false);
  assert.ok(state.ball.vy > 0, 'vy flipped exactly once — a double flip would cancel out and plow through');
  assert.equal(state.ball.vx, 0);
  assert.equal(collides(state.ball, a), false);
  assert.equal(collides(state.ball, b), false);
});

test('#1 tunnelling: a fast ball that jumps over a brick is still caught by the sweep', () => {
  const state = createState(6);
  const brick = bottomRowBricks(state, 2);
  const speed = ballSpeed(6); // 710 px/s at level 6
  const travel = speed * 0.05; // 35.5 px in one stuttered frame (cap 50 ms)
  const cx = brick.x + brick.w / 2;
  const py = brick.y + brick.h + BALL_R; // just touching below
  const y = py - travel; // fully clear above: travel > BRICK_H + 2*BALL_R

  // Sanity: a discrete check at the final position sees nothing — only a sweep
  // between the two positions can catch this hit.
  assert.equal(collides({ x: cx, y, r: BALL_R }, brick), false);

  state.ball = { x: cx, y, r: BALL_R, vx: 0, vy: -speed, px: cx, py };

  const destroyed = resolveBrickHit(state);

  assert.equal(destroyed, 2, 'the jumped-over brick and the one grazed on the way are destroyed');
  assert.equal(brick.alive, false, 'the brick the ball jumped OVER is destroyed');
  assert.ok(state.ball.vy > 0, 'the swept hit bounces the ball back down');
  assert.ok(state.ball.y >= brick.y + brick.h + BALL_R - 1e-9, 'the ball is pushed back below the brick');
  assert.equal(collides(state.ball, brick), false);
});

