edits.newText:
// --- Brick collision resolution (issue #1) --------------------------------

// A ball hit is resolved on the axis of the SMALLEST penetration: that is the
// face the ball actually crossed. A tie between a horizontal and a vertical
// face means a corner hit — both components flip. Depths within EPS of the
// minimum count as tied (float noise on an exact diagonal).
const EPS = 1e-6;

function penetrationFaces(cx, cy, r, brick) {
  const depths = [
    ['left', cx + r - brick.x],
    ['right', brick.x + brick.w - (cx - r)],
    ['top', cy + r - brick.y],
    ['bottom', brick.y + brick.h - (cy - r)],
  ];
  const min = Math.min(...depths.map(([, d]) => d));
  return depths.filter(([, d]) => d - min <= EPS).map(([name]) => name);
}

// Swept test: does the segment travelled by the ball's centre this step
// (from (px,py) to (ball.x, ball.y)) cross the brick? The brick is inflated by
// the ball radius (Minkowski sum), so a segment-vs-AABB test (slab method) is
// enough. Returns the first contact as { t, x, y, face } or null:
//   t    - contact time in [0,1]; 0 means the ball already overlapped
//   x, y - ball centre at the contact
//   face - faces hit (see penetrationFaces)
// The sweep is what makes the detection tunnelling-proof: a fast ball whose
// centre jumps OVER a brick still crosses the inflated rectangle.
function sweptHit(px, py, ball, brick) {
  const r = ball.r;
  const minX = brick.x - r;
  const maxX = brick.x + brick.w + r;
  const minY = brick.y - r;
  const maxY = brick.y + brick.h + r;
  const dx = ball.x - px;
  const dy = ball.y - py;

  let tmin = 0;
  let tmax = 1;

  if (dx === 0) {
    if (px < minX || px > maxX) return null;
  } else {
    let t1 = (minX - px) / dx;
    let t2 = (maxX - px) / dx;
    if (t1 > t2) [t1, t2] = [t2, t1];
    tmin = Math.max(tmin, t1);
    tmax = Math.min(tmax, t2);
    if (tmin > tmax) return null;
  }

  if (dy === 0) {
    if (py < minY || py > maxY) return null;
  } else {
    let t1 = (minY - py) / dy;
    let t2 = (maxY - py) / dy;
    if (t1 > t2) [t1, t2] = [t2, t1];
    tmin = Math.max(tmin, t1);
    tmax = Math.min(tmax, t2);
    if (tmin > tmax) return null;
  }

  if (tmin > 1) return null;
  const t = Math.max(0, tmin);
  const x = px + (ball.x - px) * t;
  const y = py + (ball.y - py) * t;
  return { t, x, y, face: penetrationFaces(x, y, r, brick) };
}

// Repositions the ball just OUTSIDE the brick on the face(s) it hit. Without
// this the ball still overlaps on the next frame and re-flips forever (the
// sticky bounce). For a swept contact the contact point already sits on the
// face, so this is a no-op there; for an overlap present at the start of the
// step it is the actual push-out.
function pushOut(ball, brick, faces) {
  if (faces.includes('left')) ball.x = brick.x - ball.r;
  else if (faces.includes('right')) ball.x = brick.x + brick.w + ball.r;
  if (faces.includes('top')) ball.y = brick.y - ball.r;
  else if (faces.includes('bottom')) ball.y = brick.y + brick.h + ball.r;
}

// Resolves every brick the ball touches during this step: destroys them,
// awards score, and applies EXACTLY ONE bounce (issue #1). Handles the four
// failure modes of the old code:
//   - face: smallest penetration picks the axis, the other stays untouched;
//   - corner: equal penetrations flip both components;
//   - neighbours: two bricks overlapped by the same seam are all destroyed but
//     the bounce is computed once, from the earliest contact — never per brick
//     (a double `vy = -vy` would cancel out and plow straight through);
//   - tunnelling: contacts come from sweeping the segment between the previous
//     position (recorded by step()) and the current one, so a fast ball cannot
//     jump over a brick (see sweptHit).
// Returns the number of bricks destroyed (0 when the ball hits nothing).
export function resolveBrickHit(state) {
  const { ball, bricks } = state;
  const px = ball.px ?? ball.x;
  const py = ball.py ?? ball.y;

  const hits = [];
  for (const brick of bricks) {
    if (!brick.alive) continue;
    const hit = sweptHit(px, py, ball, brick);
    if (hit) hits.push({ brick, ...hit });
  }
  if (hits.length === 0) return 0;

  hits.sort((a, b) => a.t - b.t);
  const primary = hits[0];

  for (const { brick } of hits) {
    brick.alive = false;
    state.combo += 1;
    state.score += scoreForBrick(brick, state.combo);
  }

  // Single bounce, off the face of the earliest contact.
  const faces = primary.face;
  const horizontal = faces.includes('left') || faces.includes('right');
  const vertical = faces.includes('top') || faces.includes('bottom');
  if (horizontal && vertical) {
    ball.vx = -ball.vx;
    ball.vy = -ball.vy;
  } else if (vertical) {
    ball.vy = -ball.vy;
  } else if (horizontal) {
    ball.vx = -ball.vx;
  }

  pushOut(ball, primary.brick, faces);
  return hits.length;
}

// --- Physics (movement + wall/paddle bounces) ------------------------------

// Advances the ball by a time step `dt` (in seconds) and handles bounces off
// the walls and the paddle. Does NOT handle bricks: that responsibility lives
// in resolveBrickHit(), called by frame() (issue #1 / debt #2).
// Returns `true` if the ball is lost (exits through the bottom).
export function step(state, dt) {
  const { ball, paddle } = state;

  // Remember where the ball was BEFORE this step: resolveBrickHit() sweeps the
  // segment between the two positions so a fast ball cannot tunnel (see #1).
  ball.px = ball.x;
  ball.py = ball.y;

  ball.x += ball.vx * dt;
  ball.y += ball.vy * dt;

